badExample.code:
// Bad: 200 OK with embedded error payload
HTTP/1.1 200 OK
Content-Type: application/json

{
  "success": false,
  "error": "User not found"
}

goodExample.code:
// Good: Standard 404 Not Found with RFC 7807 Problem Details
HTTP/1.1 404 Not Found
Content-Type: application/problem+json

{
  "type": "https://api.devwaymark.org/errors/user-not-found",
  "title": "User Not Found",
  "status": 404,
  "detail": "No user exists with id 'usr_98124'",
  "instance": "/api/v1/users/usr_98124"
}
